//! Signs a release manifest with an encrypted key generated by
//! `madar-release-keygen` (D35). **Run this only on the same air-gapped
//! machine the key was generated on, or an environment with the same level of trust.**
//! The raw key is never written to disk at any moment — it is decrypted
//! in memory only (`Zeroizing`) for the duration of signing, then wiped.

#![deny(unsafe_code)]

use ed25519_dalek::{Signer, SigningKey};

fn main() {
    let mut encrypted_key: Option<String> = None;
    let mut manifest: Option<String> = None;
    let mut out: Option<String> = None;

    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--encrypted-key" => encrypted_key = args.next(),
            "--manifest" => manifest = args.next(),
            "--out" => out = args.next(),
            other => {
                eprintln!("unknown argument: {other}");
                std::process::exit(2);
            }
        }
    }

    let (Some(encrypted_key), Some(manifest_path)) = (encrypted_key, manifest) else {
        eprintln!(
            "usage: madar-release-sign --encrypted-key <.enc file> --manifest <JSON file> [--out <.sig file>]"
        );
        std::process::exit(2);
    };
    let out_path = out.unwrap_or_else(|| format!("{manifest_path}.sig"));

    let enc_bytes = std::fs::read(&encrypted_key).unwrap_or_else(|e| {
        eprintln!("could not read the encrypted file {encrypted_key}: {e}");
        std::process::exit(1);
    });
    let backup = madar_keystore::EncryptedBackup::from_bytes(&enc_bytes).unwrap_or_else(|e| {
        eprintln!("invalid key file ({e:?})");
        std::process::exit(1);
    });

    let passphrase = zeroize::Zeroizing::new(
        rpassword::prompt_password("Key decryption passphrase: ")
            .expect("could not read the passphrase"),
    );

    let secret =
        madar_keystore::restore_secret(&backup, passphrase.as_str()).unwrap_or_else(|_| {
            eprintln!("decryption failed — wrong passphrase or damaged file. Nothing was signed.");
            std::process::exit(1);
        });

    let secret_bytes: zeroize::Zeroizing<[u8; 32]> =
        zeroize::Zeroizing::new(secret.as_slice().try_into().unwrap_or_else(|_| {
            eprintln!(
                "unexpected recovered key length (not 32 bytes) — the file is probably damaged."
            );
            std::process::exit(1);
        }));
    let signing_key = SigningKey::from_bytes(&secret_bytes);
    drop(secret); // Zeroizing<Vec<u8>> is wiped automatically here (keystore INV-K3)

    let manifest_bytes = std::fs::read(&manifest_path).unwrap_or_else(|e| {
        eprintln!("could not read the manifest {manifest_path}: {e}");
        std::process::exit(1);
    });

    let signature = signing_key.sign(&manifest_bytes);
    std::fs::write(&out_path, signature.to_bytes()).unwrap_or_else(|e| {
        eprintln!("failed to write the signature file {out_path}: {e}");
        std::process::exit(1);
    });

    println!("manifest signed successfully: {out_path}");
    println!(
        "quick manual check (optional): madar-node check-update --manifest-file {manifest_path} --signature-file {out_path} --trusted-key <your public key>"
    );
}
